// SAT 신규 13세트 + 오류 신고 수정본을 **순수 SQL 파일**로 만든다(서비스 키 불필요 — 총괄이 `npx supabase db query --linked -f <파일>` 로 순서대로 실행).
// 이 스크립트는 DB 에 쓰지 않는다. 현재 상태 확인용 읽기 SELECT(`supabase db query --linked`)만 쓴다(패치 대상 문항의 현재 공개 버전 / 새 세트 Math 결함 점검).
//   npx tsx scripts/prod-open/sat-expand-sql.ts [--out data/prod-open/sat-expand-sql] [--offline-readout <file>]
// 산출(각 5MB 이하): 00_preflight · 01_import_NN(R&W 신규 임포트+공개) · 02_keywords · 03_slot_import(교체용 컴파일러 문항) · 04_patches(문항 새 버전) ·
//   05_new_sets(Practice Test 14~26 초안) · 06_old_set_versions(Test 1~13 새 세트 버전 초안) · 07_verify(읽기) · 99_rollback.
// 전 파일 멱등(이미 있으면 건너뜀), 충돌·검증 실패는 그 세트만 건너뛰고 NOTICE 로 알린다. 삭제·덮어쓰기 없음, 공개 없음(초안까지).
import { spawnSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { findResidue } from "../../lib/problem-generation/residue";
import { dedupeStem, answerKeyError, draftBankGateError } from "../../lib/problem-text-guards";
import { judgeMaterialNeed, materialBlocker } from "../../lib/problem-material-need";
import { checkFigure } from "../../lib/problem-figures/check";
import { validateFigureSpec } from "../../lib/problem-figures/spec";
import { checkContent } from "../../lib/problem-content-check";
import { composeProblemText } from "../../lib/problem-question";
import { SKILL_BY_CODE } from "../../lib/problem-taxonomy";
import { findProblemSkill } from "../../lib/problem-skills";
import { resolveIntendedSkill } from "../keywords/intended-skill";
import { SAT_KEYWORD_BY_SKILL } from "../../lib/sat-keywords/taxonomy";
import { planPatch, type Patch, type PatchPlan, type ProblemReadout } from "../../lib/audit-fix/plan";
import { planSatErrorReportFix, type SatRow } from "../../lib/audit-fix/sat-error-report-1018";
import { emitApplySql, emitRollbackSql, toSqlPlan } from "../../lib/audit-fix/sql";
import { PROBLEM_SELECT } from "../audit/apply-audit-fixes";

const arg = (n: string) => { const i = process.argv.indexOf(n); return i > 0 ? process.argv[i + 1] : undefined; };
const OUT = path.resolve(arg("--out") ?? "data/prod-open/sat-expand-sql");
const rd = <T,>(p: string) => JSON.parse(readFileSync(path.resolve(p), "utf-8")) as T;
const EXPAND = "data/mock-exam-generation/sat-expand-20261015/final";
const ER = "data/mock-exam-generation/sat-error-report-1018";
const MAX_BYTES = 3_500_000;
const TAG = "satx";
const lit = (v: unknown) => { const s = JSON.stringify(v); if (s.includes(`$${TAG}$`)) throw new Error("dollar tag in data"); return `$${TAG}$${s}$${TAG}$::jsonb`; };
const strLit = (s: string) => `'${s.replace(/'/g, "''")}'`;
const ADMIN = "(select id from profiles where role = 'admin' order by created_at limit 1)";
const HEADER = (what: string) => `-- ${what}\n-- generated by scripts/prod-open/sat-expand-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; no deletes/overwrites; nothing is published here (drafts only).\n`;

function dbRows<T = any>(sql: string): T[] {
  const r = spawnSync("supabase", ["db", "query", "--linked", sql], { encoding: "utf-8", maxBuffer: 512 * 1024 * 1024 });
  if (r.status !== 0) throw new Error(`supabase db query 실패: ${(r.stderr || r.stdout).slice(0, 400)}`);
  const o = r.stdout; return (JSON.parse(o.slice(o.indexOf("{"), o.lastIndexOf("}") + 1)) as { rows: T[] }).rows;
}
const uuidArr = (ids: string[]) => `array[${ids.map((i) => `'${i}'`).join(",")}]::uuid[]`;
const chunk = <T,>(xs: T[], n: number) => { const o: T[][] = []; for (let i = 0; i < xs.length; i += n) o.push(xs.slice(i, i + n)); return o; };

// ── 임포트 레코드(import.ts 와 같은 게이트·검사) ─────────────
type Rec = { gid: string; runId: string; skill: string; planSkill?: string; domain: string; examSystem: string; difficulty: string; format: "mc" | "spr"; problem: any; quality: Record<string, any>; review?: unknown; recipeId?: string | null; recipeCheck?: unknown; difficultyStatus?: string; createdVia?: string; subpattern?: string | null };
function buildImport(recs: Rec[]) {
  const ok: Record<string, unknown>[] = []; const rejected: string[] = [];
  for (const r of recs) {
    const g = r.problem; const question = g.question ?? null;
    const stimulus = dedupeStem(g.stimulus ?? g.passage ?? "", question);
    const residue = findResidue({ passage: g.passage, stimulus: g.stimulus, question: g.question, options: g.options, explanation: g.explanation, explanationEn: g.explanationEn, statements: g.statements });
    if (residue.length) { rejected.push(`${r.gid}: 잔재`); continue; }
    const keyErr = r.format === "mc" ? answerKeyError(g.options ?? null, g.correctIndex ?? null) : null;
    const gateErr = draftBankGateError({ examSystem: r.examSystem, usageScope: "mock_exam", passage: stimulus, question, options: g.options ?? null, statements: g.statements ?? null, explanationEn: g.explanationEn ?? null });
    const matErr = materialBlocker(judgeMaterialNeed({ examSystem: r.examSystem, skillCode: r.skill, text: composeProblemText(stimulus, question) }), g.figure ?? null);
    if (keyErr ?? gateErr ?? matErr) { rejected.push(`${r.gid}: 게이트 거절 ${String(keyErr ?? gateErr ?? matErr).slice(0, 120)}`); continue; }
    const fullText = composeProblemText(stimulus, question);
    const contentIssues = checkContent({ format: r.format, passage: fullText, options: g.options ?? null, correctIndex: g.correctIndex ?? null, explanation: g.explanation, answers: g.answers ?? null, statements: g.statements ?? null, skillCode: r.skill, figure: g.figure ?? null });
    const figureCheck = checkFigure(g.figure ?? null, fullText, g.options ?? null, g.correctIndex ?? null);
    const figureToSave = g.figure == null ? null : (() => { const fv = validateFigureSpec(g.figure); return fv.ok ? fv.spec : g.figure; })();
    const check = { ...figureCheck, issues: [...figureCheck.issues, ...contentIssues], ok: figureCheck.ok && contentIssues.length === 0 };
    const skill = SKILL_BY_CODE.get(r.skill)!; const legacy = findProblemSkill(skill.legacySkill);
    const myGroup = r.quality.mockExamGeneration?.archetypeId ?? null;
    ok.push({ gid: r.gid, subject: r.examSystem === "sat_rw" ? "SAT Reading & Writing" : "SAT Math", format: r.format, skillType: legacy?.label ?? skill.label, difficulty: r.difficulty, skill: r.skill, examSystem: r.examSystem,
      createdVia: r.createdVia === "compiler" ? "compiler" : "ai_generated", subpattern: r.subpattern ?? null, group: myGroup, passage: stimulus, question: question?.trim() || null, options: g.options ?? null, correctIndex: g.correctIndex ?? null, answers: g.answers ?? null,
      explanation: g.explanation, explanationEn: g.explanationEn || null, figure: figureToSave, statements: g.statements?.length ? g.statements : null, evidenceTarget: g.evidenceTarget ?? null, evidenceSpan: g.evidenceSpan ?? null, answerRationale: g.answerRationale ?? null, distractorErrorTypes: g.distractorErrorTypes ?? null,
      renderCheck: check, publish: check.ok,
      quality: { ...r.quality, mockExamGeneration: { ...(r.quality.mockExamGeneration ?? {}), runId: r.runId, gid: r.gid, intendedSkill: r.planSkill ?? r.skill, recipeId: r.recipeId ?? null, recipeCheck: r.recipeCheck ?? null, hardBasis: r.recipeId ? (r.createdVia === "compiler" ? "compiler_archetype" : "recipe") : null, difficultyStatus: r.difficultyStatus ?? (r.quality.mockExamGeneration?.difficultyStatus ?? null), review: r.review ?? null } } });
  }
  return { ok, rejected };
}
const importSql = (items: unknown[], what: string) => `${HEADER(what)}
do $imp$
declare
  v_items constant jsonb := ${lit(items)};
  v_actor uuid := ${ADMIN};
  r jsonb; v_pid uuid; v_vid uuid; v_n int := 0; v_skip int := 0;
begin
  if v_actor is null then raise exception 'No admin profile found.'; end if;
  for r in select * from jsonb_array_elements(v_items) loop
    if exists (select 1 from problem_versions where quality->'mockExamGeneration'->>'gid' = r->>'gid') then v_skip := v_skip + 1; continue; end if;
    v_pid := public.create_bank_problem(p_subject_id => (select id from subjects where name = r->>'subject' and archived_at is null), p_format => r->>'format', p_skill_type => r->>'skillType', p_topic => '',
      p_difficulty => r->>'difficulty', p_actor_id => v_actor, p_skill_code => r->>'skill', p_exam_system => r->>'examSystem', p_ap_subject => null, p_usage_scope => 'mock_exam');
    update problems set created_via = r->>'createdVia', subpattern = coalesce(r->>'subpattern', subpattern), similarity_group = coalesce(r->>'group', similarity_group) where id = v_pid;
    v_vid := public.save_problem_draft_version(p_problem_id => v_pid, p_passage => r->>'passage', p_options => nullif(r->'options', 'null'::jsonb), p_correct_index => (r->>'correctIndex')::int, p_explanation => r->>'explanation',
      p_difficulty => r->>'difficulty', p_actor_id => v_actor, p_answers => nullif(r->'answers', 'null'::jsonb), p_figure => nullif(r->'figure', 'null'::jsonb), p_figure_checked => false, p_statements => nullif(r->'statements', 'null'::jsonb),
      p_question => r->>'question', p_repair_status => null, p_explanation_en => r->>'explanationEn', p_evidence_target => r->>'evidenceTarget', p_evidence_span => r->>'evidenceSpan', p_answer_rationale => r->>'answerRationale',
      p_distractor_error_types => nullif(r->'distractorErrorTypes', 'null'::jsonb));
    perform public.set_problem_render_check(v_vid, r->'renderCheck');
    perform public.set_problem_quality(v_vid, r->'quality');
    if (r->>'publish')::boolean then perform public.confirm_and_publish_problem_version(v_vid, v_actor); end if;
    v_n := v_n + 1;
  end loop;
  raise notice '${what}: created=% skipped(existing)=%', v_n, v_skip;
end
$imp$;
`;
function writeChunks(prefix: string, recs: Record<string, unknown>[], what: string, files: { name: string; bytes: number }[]) {
  const parts: Record<string, unknown>[][] = []; let cur: Record<string, unknown>[] = []; let sz = 0;
  for (const r of recs) { const b = JSON.stringify(r).length; if (sz + b > MAX_BYTES && cur.length) { parts.push(cur); cur = []; sz = 0; } cur.push(r); sz += b; }
  if (cur.length) parts.push(cur);
  parts.forEach((p, i) => { const name = `${prefix}${parts.length > 1 ? `_${String(i + 1).padStart(2, "0")}` : ""}.sql`; const body = importSql(p, `${what} ${i + 1}/${parts.length}`); writeFileSync(path.join(OUT, name), body); files.push({ name, bytes: body.length }); });
}

// ── 세트 SQL ───────────────────────────────────────────────
const SET_COLS = `select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_sets' and is_generated = 'NEVER'`;
const VALIDATE = (label: string) => `
    if not coalesce((public.mock_exam_validate_mst_set(v_new)->>'ready')::boolean, false) then raise exception '${label}: 4-module/rule validation failed %', public.mock_exam_validate_mst_set(v_new)::text; end if;
    select string_agg(x.problem_id::text || ':' || x.issue, ', ') into v_bad from (select * from public.mock_exam_set_item_issues(v_new) where issue is not null limit 5) x;
    if v_bad is not null then raise exception '${label}: item issues %', v_bad; end if;
    update mock_exam_sets set readiness_status = 'ready', readiness_report = public.mock_exam_validate_mst_set(v_new) || jsonb_build_object('shortfalls', '[]'::jsonb, 'checkedAt', now()), readiness_checked_at = now() where id = v_new;`;

function newSetSql(set: { name: string; items: any[] }) {
  return `do $ns$
declare
  v_set constant jsonb := ${lit(set)};
  v_actor uuid := ${ADMIN}; v_tpl mock_exam_sets%rowtype; v_new uuid := gen_random_uuid(); v_cols text; it jsonb; v_pid uuid; v_p problems%rowtype; v_bad text;
begin
  if exists (select 1 from mock_exam_sets where name = v_set->>'name' and archived_at is null and status <> 'archived') then raise notice '% already exists (non-archived) - skipped', v_set->>'name'; return; end if;
  begin
    select * into v_tpl from mock_exam_sets where name = 'SAT Practice Test 13' and status = 'published' and archived_at is null limit 1;
    if v_tpl.id is null then raise exception 'template set (Test 13 published) missing'; end if;
    ${SET_COLS} and column_name not in ('id', 'set_group_id', 'version_no', 'name', 'status', 'created_by', 'created_at', 'published_at', 'published_by', 'archived_at', 'access_tier', 'readiness_status', 'readiness_report', 'readiness_checked_at');
    execute format('insert into mock_exam_sets (id, name, status, created_by, access_tier, %s) select $1, $2, ''draft'', $3, ''tutoring'', %s from mock_exam_sets where id = $4', v_cols, v_cols) using v_new, v_set->>'name', v_actor, v_tpl.id;
    for it in select * from jsonb_array_elements(v_set->'items') loop
      v_pid := coalesce((it->>'problemId')::uuid, (select problem_id from problem_versions where quality->'mockExamGeneration'->>'gid' = it->>'gid' limit 1));
      select * into v_p from problems where id = v_pid;
      if v_p.id is null or v_p.status <> 'confirmed' or v_p.archived_at is not null or v_p.published_version_id is null then raise exception 'item % % not usable (problem %)', it->>'section', it->>'position', v_pid; end if;
      insert into mock_exam_set_items (exam_set_id, section, position, problem_id, problem_version_id, sat_domain, skill_code, difficulty, module_key, route)
      values (v_new, it->>'section', (it->>'position')::int, v_pid, v_p.published_version_id, it->>'domain', it->>'skill', it->>'difficulty', (it->>'moduleKey')::mock_exam_module_key, nullif(it->>'route', '')::mock_exam_route);
    end loop;${VALIDATE("new set")}
    raise notice '% created as draft (%)', v_set->>'name', v_new;
  exception when others then raise notice '% SKIPPED: %', v_set->>'name', sqlerrm;
  end;
end
$ns$;
`;
}

type OldSpec = { name: string; repointProblemIds: string[]; newMeta?: boolean; slots: { section: string; position: number; oldVersionId: string; newGid?: string; newProblemId?: string }[] };
function oldSetSql(sp: OldSpec) {
  return `do $os$
declare
  v_sp constant jsonb := ${lit(sp)};
  v_actor uuid := ${ADMIN}; v_src mock_exam_sets%rowtype; v_new uuid := gen_random_uuid(); v_cols text; v_cols_i text; v_pids uuid[]; sl jsonb; v_npid uuid; v_p problems%rowtype; v_stale int; v_slots int := 0; v_bad text; v_slotsj jsonb := '[]'::jsonb;
begin
  begin
    select * into v_src from mock_exam_sets where name = v_sp->>'name' and status = 'published' and archived_at is null for update;
    if v_src.id is null then raise exception 'published % not found', v_sp->>'name'; end if;
    select array_agg(x::uuid) into v_pids from jsonb_array_elements_text(v_sp->'repointProblemIds') x;
    v_pids := coalesce(v_pids, array[]::uuid[]);
    select count(*) into v_stale from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = v_src.id and i.problem_id = any (v_pids) and p.published_version_id is distinct from i.problem_version_id;
    for sl in select * from jsonb_array_elements(v_sp->'slots') loop
      if exists (select 1 from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'section' and i.position = (sl->>'position')::int and i.problem_version_id = (sl->>'oldVersionId')::uuid) then v_slots := v_slots + 1; end if;
    end loop;
    if v_stale = 0 and v_slots = 0 then raise notice '% nothing to change (already up to date) - skipped', v_src.name; return; end if;
    if exists (select 1 from mock_exam_sets where set_group_id = v_src.set_group_id and status = 'draft') then raise notice '% a draft version already exists - skipped (publish/discard it, then re-run)', v_src.name; return; end if;
    perform pg_advisory_xact_lock(hashtextextended('mock_exam_new_version:' || v_src.set_group_id::text, 0));
    ${SET_COLS} and column_name not in ('id', 'version_no', 'status', 'created_by', 'created_at', 'published_at', 'published_by', 'archived_at', 'access_tier', 'readiness_status', 'readiness_report', 'readiness_checked_at');
    execute format('insert into mock_exam_sets (id, version_no, status, created_by, access_tier, %s) select $1, $2, ''draft'', $3, ''tutoring'', %s from mock_exam_sets where id = $4', v_cols, v_cols)
      using v_new, (select max(version_no) + 1 from mock_exam_sets where set_group_id = v_src.set_group_id), v_actor, v_src.id;
    -- 교체 칸 목록(이 세트에서 아직 옛 문항인 칸만)
    for sl in select * from jsonb_array_elements(v_sp->'slots') loop
      if exists (select 1 from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'section' and i.position = (sl->>'position')::int and i.problem_version_id = (sl->>'oldVersionId')::uuid) then v_slotsj := v_slotsj || jsonb_build_array(sl); end if;
    end loop;
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
           string_agg(case column_name when 'problem_version_id' then 'case when i.problem_id = any ($3) then coalesce(p.published_version_id, i.problem_version_id) else i.problem_version_id end'
                                       when 'content_snapshot' then 'case when i.problem_id = any ($3) then null else i.content_snapshot end' else 'i.' || quote_ident(column_name) end, ', ' order by ordinal_position)
      into v_cols, v_cols_i from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_set_items' and is_generated = 'NEVER' and column_name not in ('id', 'exam_set_id', 'created_at');
    execute format('insert into mock_exam_set_items (exam_set_id, %s) select $1, %s from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = $2
                    and not exists (select 1 from jsonb_to_recordset($4) as x(section text, position int) where x.section = i.section and x.position = i.position)', v_cols, v_cols_i) using v_new, v_src.id, v_pids, v_slotsj;
    for sl in select * from jsonb_array_elements(v_slotsj) loop
      v_npid := coalesce((sl->>'newProblemId')::uuid, (select problem_id from problem_versions where quality->'mockExamGeneration'->>'gid' = sl->>'newGid' limit 1));
      select * into v_p from problems where id = v_npid;
      if v_p.id is null or v_p.status <> 'confirmed' or v_p.archived_at is not null or v_p.published_version_id is null then raise exception 'replacement for slot %/% not usable (%)', sl->>'section', sl->>'position', coalesce(sl->>'newGid', sl->>'newProblemId'); end if;
      if exists (select 1 from mock_exam_set_items x where x.problem_id = v_npid and x.exam_set_id in (select id from mock_exam_sets where archived_at is null and status <> 'archived' and id <> v_new)) then raise exception 'replacement % already used in another live set', v_npid; end if;
      insert into mock_exam_set_items (exam_set_id, section, position, problem_id, problem_version_id, sat_domain, skill_code, difficulty, module_key, route)
      select v_new, i.section, i.position, v_npid, v_p.published_version_id, ${sp.newMeta ? 'v_p.sat_domain, v_p.skill_code, v_p.difficulty' : 'i.sat_domain, i.skill_code, i.difficulty'}, i.module_key, i.route from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'section' and i.position = (sl->>'position')::int;
    end loop;${VALIDATE("old set new version")}
    raise notice '% new draft version created (% repointed items, % replaced slots) -> %', v_src.name, v_stale, v_slots, v_new;
  exception when others then raise notice '% SKIPPED: %', v_sp->>'name', sqlerrm;
  end;
end
$os$;
`;
}

// ══ 27~30: SAT 정량 근거(표·그래프) 문항 반영 — `SAT_QUANT=1 npx tsx scripts/prod-open/sat-expand-sql.ts` (백로그 A4, 입력은 파일뿐 / 원격 쓰기 없음) ══
if (process.env.SAT_QUANT) {
  const DQ = "data/mock-exam-generation/sat-quant-20261020/final";
  const adoptedQ = rd<Rec[]>(`${DQ}/adopted-all.json`);
  const oldsQ = rd<OldSpec[]>(`${DQ}/old-set-specs.json`);
  mkdirSync(OUT, { recursive: true });
  const filesQ: { name: string; bytes: number }[] = [];
  const emQ = (n: string, b: string) => { writeFileSync(path.join(OUT, n), b); filesQ.push({ name: n, bytes: b.length }); };
  const HQ = (w: string) => `-- ${w}\n-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_QUANT=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.\n`;
  const impQ = buildImport(adoptedQ);
  const repQ = { total: adoptedQ.length, ok: impQ.ok.length, rejected: impQ.rejected };
  if (impQ.rejected.length) { console.error("게이트 거절:", impQ.rejected); }
  writeChunks("27_import_quant", impQ.ok, "SAT R&W import (quant evidence)", filesQ);
  const okQ = new Set(impQ.ok.map((x) => x.gid as string));
  const usedGids = new Set(oldsQ.flatMap((o) => o.slots.map((sl) => sl.newGid!)));
  const missingQ = [...usedGids].filter((g) => !okQ.has(g));
  if (missingQ.length) { console.error("교체 명세가 거절된 gid 를 씀:", missingQ); process.exit(1); }
  const kwQ: Record<string, string> = {};
  for (const r of adoptedQ) { if (!okQ.has(r.gid)) continue; const d = SAT_KEYWORD_BY_SKILL.get(r.skill); if (d) kwQ[r.gid] = d.skillCode; }
  const namesQ = oldsQ.map((x) => x.name); const nameArrQ = `array[${namesQ.map((n) => strLit(n)).join(",")}]`; const gidArrQ = `array[${adoptedQ.map((r) => strLit(r.gid)).join(",")}]`;
  emQ("27_preflight.sql", `${HQ("preflight for 27-30 (SELECT only): target sets - drafts, quant-evidence count, attempts; already-imported quant gids")}
select s.name, s.version_no, s.status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and i.skill_code = 'command_of_evidence_quant') as quant_items,
  (select count(*) from mock_exam_sets d where d.set_group_id = s.set_group_id and d.status = 'draft' and d.archived_at is null) as existing_drafts,
  (select count(*) from mock_exam_attempts a where a.exam_set_id = s.id) as attempts
from mock_exam_sets s where s.name = any (${nameArrQ}) and s.status = 'published' and s.archived_at is null order by length(s.name), s.name;
select count(*) as already_imported_quant_gids from problem_versions where quality->'mockExamGeneration'->>'gid' = any (${gidArrQ});
`);
  emQ("28_keywords_quant.sql", `${HQ("link imported quant-evidence problems to skill keywords")}
do $kw$
declare v_map constant jsonb := ${lit(kwQ)}; v_n int;
begin
  insert into problem_keywords (problem_id, keyword_id)
  select distinct p.id, k.id from jsonb_each_text(v_map) m
    join problem_versions pv on pv.quality->'mockExamGeneration'->>'gid' = m.key
    join problems p on p.id = pv.problem_id and p.archived_at is null
    join subject_keywords k on k.subject_id = p.subject_id and k.skill_code = m.value
  on conflict (problem_id, keyword_id) do nothing;
  get diagnostics v_n = row_count;
  raise notice 'keyword links inserted: % (of % mapped gids)', v_n, (select count(*) from jsonb_object_keys(v_map));
end
$kw$;
`);
  emQ("29_set_versions_quant.sql", `${HQ("new draft set versions: Command of Evidence (Textual) slots replaced by quantitative-evidence (table/graph) items (published sets/attempts/old versions untouched; a set with an existing draft is skipped)")}\n${oldsQ.map(oldSetSql).join("\n")}`);
  emQ("30_verify_quant.sql", `${HQ("verify after 27-29 (SELECT only)")}
select s.name, s.version_no, s.status, s.readiness_status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items,
  (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and i.skill_code = 'command_of_evidence_quant') as quant_items
from mock_exam_sets s where s.status = 'draft' and s.archived_at is null and s.name = any (${nameArrQ}) order by length(s.name), s.name;
select count(*) as imported_quant_problems, count(*) filter (where p.status = 'confirmed') as confirmed from problem_versions pv join problems p on p.id = pv.problem_id where pv.quality->'mockExamGeneration'->>'gid' = any (${gidArrQ});
select count(*) as published_sets_total from mock_exam_sets where status = 'published' and archived_at is null;
`);
  emQ("99_rollback_quant.sql", `${HQ("ROLLBACK of 27-30: deletes the new draft set versions of the target sets (no attempts can reference a draft) and archives imported quant problems no live set uses. Published sets untouched.")}
do $rbq$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.name = any (${nameArrQ}) and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no);
  get diagnostics v_n = row_count; raise notice 'draft set versions removed: %', v_n;
  delete from problem_keywords where problem_id in (select pv.problem_id from problem_versions pv where pv.quality->'mockExamGeneration'->>'gid' = any (${gidArrQ}));
  update problems p set archived_at = now() where p.archived_at is null and p.id in (select pv.problem_id from problem_versions pv where pv.quality->'mockExamGeneration'->>'gid' = any (${gidArrQ}))
    and not exists (select 1 from mock_exam_set_items i join mock_exam_sets o on o.id = i.exam_set_id and o.archived_at is null and o.status <> 'archived' where i.problem_id = p.id);
  get diagnostics v_n = row_count; raise notice 'quant problems archived: %', v_n;
end $rbq$;
`);
  writeFileSync(path.join(OUT, "manifest_quant.json"), JSON.stringify({ files: filesQ, report: repQ }, null, 1));
  console.log(JSON.stringify({ files: filesQ, report: repQ }));
  process.exit(0);
}

// ══ 09: 수동 패치(E1019-M*) 17건을 새 세트 버전 초안으로 반영 — `SAT_09=1 npx tsx scripts/prod-open/sat-expand-sql.ts` (원격은 읽기 SELECT 만, 08 적용 후 기준) ══
if (process.env.SAT_09) {
  const M_IDS = rd<{ items: { problemId: string }[] }>("data/prod-open/sat-expand-sql/08_manual_patches.report.json").items.map((i) => i.problemId);
  const idsLit = uuidArr(M_IDS);
  mkdirSync(OUT, { recursive: true });
  const live9 = dbRows<{ name: string; problem_ids: string[] }>(`select s.name, array_agg(i.problem_id) as problem_ids from mock_exam_sets s join mock_exam_set_items i on i.exam_set_id = s.id join problems p on p.id = i.problem_id where s.status = 'published' and s.archived_at is null and s.name ~ '^SAT Practice Test [0-9]+$' and i.problem_id = any (${idsLit}) and p.published_version_id is distinct from i.problem_version_id group by s.name`);
  const specs9: OldSpec[] = live9.map((s) => ({ name: s.name, repointProblemIds: s.problem_ids, slots: [] })).sort((a, b) => Number(a.name.match(/\d+/)![0]) - Number(b.name.match(/\d+/)![0]));
  const names9 = specs9.map((s) => s.name);
  const H9 = (w: string) => `-- ${w}\n-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_09=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.\n`;
  const nameArr = `array[${names9.map((n) => strLit(n)).join(",")}]`;
  writeFileSync(path.join(OUT, "09_set_versions_manual.sql"), `${H9("new draft set versions pointing at the E1019-M* patched problem versions")}\n${specs9.map(oldSetSql).join("\n")}`);
  writeFileSync(path.join(OUT, "09_preflight.sql"), `${H9("preflight for 09 (SELECT only): 08 applied? sets with stale items / existing drafts")}
select s.name, s.version_no, count(*) filter (where p.published_version_id is distinct from i.problem_version_id and i.problem_id = any (${idsLit})) as stale_manual_items,
  (select count(*) from mock_exam_sets d where d.set_group_id = s.set_group_id and d.status = 'draft') as existing_drafts
from mock_exam_sets s join mock_exam_set_items i on i.exam_set_id = s.id join problems p on p.id = i.problem_id
where s.status = 'published' and s.archived_at is null and s.name = any (${nameArr}) group by s.name, s.version_no, s.set_group_id order by length(s.name), s.name;
select count(*) as patched_08_versions from problems p join problem_versions pv on pv.id = p.published_version_id where p.id = any (${idsLit}) and pv.quality->'auditFix'->>'patch' like 'E1019-M%';
`);
  writeFileSync(path.join(OUT, "09_verify.sql"), `${H9("verify after 09 (SELECT only)")}
select s.name, s.version_no, s.status, s.readiness_status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items,
  (select count(*) from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = s.id and i.problem_id = any (${idsLit}) and p.published_version_id = i.problem_version_id) as manual_items_on_new_version,
  (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and i.problem_id = any (${idsLit})) as manual_items
from mock_exam_sets s where s.status = 'draft' and s.archived_at is null and s.name = any (${nameArr}) order by length(s.name), s.name;
select count(*) as published_sets_unchanged from mock_exam_sets where status = 'published' and archived_at is null;
`);
  writeFileSync(path.join(OUT, "99_set_versions_manual_rollback.sql"), `${H9("ROLLBACK of 09: removes only the draft set versions created for these sets (no attempts can reference a draft). Published sets untouched.")}
do $rb9$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.name = any (${nameArr}) and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no);
  get diagnostics v_n = row_count; raise notice 'draft set versions removed: %', v_n;
end $rb9$;
`);
  console.log("09 sets:", specs9.map((s) => `${s.name}:${s.repointProblemIds.length}`).join(", "));
  process.exit(0);
}

// ══ 16~22: 문학(literature_fiction) 25% 조정(2026-10-19) — `SAT_LIT25=1 npx tsx scripts/prod-open/sat-expand-sql.ts` (원격 쓰기 없음, 입력은 파일뿐) ══
// 입력(data/mock-exam-generation/sat-lit25-20261019/final): adopted-all.json(비문학 신규 R&W), new-sets-resolved.json(T27~30 새 구성), old-set-specs.json(T4~T9 새 세트 버전 교체 칸).
// 산출: 16_preflight(읽기) · 17_release_old_drafts_27_30 · 18_import_lit25_NN · 19_keywords_lit25 · 20_new_sets_27_30_lit25 · 21_old_set_versions_lit25 · 22_verify_lit25(읽기) · 99_rollback_lit25.
// 순서: 16 -> 17 -> 18 -> 19 -> 20 -> 21 -> 22. 전부 멱등(17 은 "새 문항이 하나도 없는 옛 구성 초안"만 지우므로 20 이후 재실행해도 새 초안을 건드리지 않는다). 공개 없음(초안까지).
if (process.env.SAT_LIT25) {
  const DL = "data/mock-exam-generation/sat-lit25-20261019/final";
  const adoptedL = rd<Rec[]>(`${DL}/adopted-all.json`);
  const setsL = rd<{ sets: { name: string; items: any[] }[] }>(`${DL}/new-sets-resolved.json`).sets;
  const oldsL = rd<OldSpec[]>(`${DL}/old-set-specs.json`);
  mkdirSync(OUT, { recursive: true });
  const filesL: { name: string; bytes: number }[] = []; const repL: Record<string, unknown> = {};
  const emL = (n: string, b: string) => { writeFileSync(path.join(OUT, n), b); filesL.push({ name: n, bytes: b.length }); };
  const HL = (w: string) => `-- ${w}\n-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_LIT25=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.\n`;
  const impL = buildImport(adoptedL);
  repL.import = { total: adoptedL.length, ok: impL.ok.length, rejected: impL.rejected };
  writeChunks("18_import_lit25", impL.ok, "SAT R&W import (lit25)", filesL);
  const okL = new Set(impL.ok.map((x) => x.gid as string));
  const kwL: Record<string, string> = {};
  for (const r of adoptedL) { if (!okL.has(r.gid)) continue; const sk = resolveIntendedSkill({ quality: r.quality, skillCode: r.skill, planSkillFromFile: r.planSkill }).skill; const d = sk ? SAT_KEYWORD_BY_SKILL.get(sk) : undefined; if (d) kwL[r.gid] = d.skillCode; }
  const names30L = setsL.map((x) => x.name); const namesOldL = oldsL.map((x) => x.name); const gidsL = adoptedL.map((r) => r.gid);
  const nameArr30L = `array[${names30L.map((n) => strLit(n)).join(",")}]`; const nameArrOldL = `array[${namesOldL.map((n) => strLit(n)).join(",")}]`;
  const gidArrL = `array[${gidsL.map((g) => strLit(g)).join(",")}]`;
  emL("16_preflight.sql", `${HL("preflight for 16-22 (SELECT only): T27-30 drafts, T4-T9 published/drafts, template, already-imported lit25 gids")}
select s.name, s.version_no, s.status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items,
  (select count(*) from mock_exam_set_items i join problem_versions pv on pv.problem_id = i.problem_id and pv.quality->'mockExamGeneration'->>'gid' = any (${gidArrL}) where i.exam_set_id = s.id) as lit25_items,
  (select count(*) from mock_exam_attempts a where a.exam_set_id = s.id) as attempts
from mock_exam_sets s where (s.name = any (${nameArr30L}) or s.name = any (${nameArrOldL})) and s.archived_at is null order by length(s.name), s.name, s.version_no;
select count(*) as already_imported_lit25_gids from problem_versions where quality->'mockExamGeneration'->>'gid' = any (${gidArrL});
select count(*) as template_set_ok from mock_exam_sets where name = 'SAT Practice Test 13' and status = 'published' and archived_at is null;
`);
  emL("17_release_old_drafts_27_30.sql", `${HL("removes the OLD-composition draft sets 27-30 (drafts without any lit25 item, no attempts) so the new composition can be created; problems stay in the bank")}
do $rel$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.name = any (${nameArr30L}) and s.archived_at is null
    and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and not exists (select 1 from mock_exam_set_items i join problem_versions pv on pv.problem_id = i.problem_id and pv.quality->'mockExamGeneration'->>'gid' = any (${gidArrL}) where i.exam_set_id = s.id);
  get diagnostics v_n = row_count; raise notice 'old-composition draft sets removed: %', v_n;
end $rel$;
`);
  emL("19_keywords_lit25.sql", `${HL("link imported lit25 R&W problems to skill keywords")}
do $kw$
declare v_map constant jsonb := ${lit(kwL)}; v_n int;
begin
  insert into problem_keywords (problem_id, keyword_id)
  select distinct p.id, k.id from jsonb_each_text(v_map) m
    join problem_versions pv on pv.quality->'mockExamGeneration'->>'gid' = m.key
    join problems p on p.id = pv.problem_id and p.archived_at is null
    join subject_keywords k on k.subject_id = p.subject_id and k.skill_code = m.value
  on conflict (problem_id, keyword_id) do nothing;
  get diagnostics v_n = row_count;
  raise notice 'keyword links inserted: % (of % mapped gids)', v_n, (select count(*) from jsonb_object_keys(v_map));
end
$kw$;
`);
  emL("20_new_sets_27_30_lit25.sql", `${HL("Practice Test 27~30 - draft sets, literature ~25% composition (never published here)")}\n${setsL.map(newSetSql).join("\n")}`);
  emL("21_old_set_versions_lit25.sql", `${HL("Test 4~9 - new draft set versions replacing excess literature items with non-literature items (published sets/attempts/old versions untouched)")}\n${oldsL.map(oldSetSql).join("\n")}`);
  emL("22_verify_lit25.sql", `${HL("verify after 16-21 (SELECT only)")}
select s.name, s.version_no, s.status, s.readiness_status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items,
  (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and i.section = 'rw') as rw,
  (select count(*) from mock_exam_set_items i join mock_exam_set_items j on j.problem_id = i.problem_id and j.exam_set_id <> i.exam_set_id join mock_exam_sets o on o.id = j.exam_set_id and o.archived_at is null and o.status <> 'archived' and o.set_group_id <> s.set_group_id where i.exam_set_id = s.id) as items_shared_with_other_live_sets
from mock_exam_sets s where s.status = 'draft' and s.archived_at is null and (s.name = any (${nameArr30L}) or s.name = any (${nameArrOldL})) order by length(s.name), s.name;
select count(*) as imported_lit25_problems, count(*) filter (where p.status = 'confirmed') as confirmed from problem_versions pv join problems p on p.id = pv.problem_id where pv.quality->'mockExamGeneration'->>'gid' = any (${gidArrL});
select count(*) as published_sets_total from mock_exam_sets where status = 'published' and archived_at is null;
`);
  emL("99_rollback_lit25.sql", `${HL("ROLLBACK of 16-22: deletes the T4-T9 new-version drafts and the T27-30 drafts (no attempts), unlinks/archives lit25 problems no live set uses. To restore the previous T27-30 drafts re-run 14_new_sets_27_30.sql afterwards. Published sets untouched.")}
do $rbl$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.name = any (${nameArrOldL}) and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no);
  get diagnostics v_n = row_count; raise notice 'T4-T9 draft set versions removed: %', v_n;
  delete from mock_exam_sets s where s.status = 'draft' and s.name = any (${nameArr30L}) and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id);
  get diagnostics v_n = row_count; raise notice 'T27-30 draft sets removed: %', v_n;
  delete from problem_keywords where problem_id in (select pv.problem_id from problem_versions pv where pv.quality->'mockExamGeneration'->>'gid' = any (${gidArrL}));
  update problems p set archived_at = now() where p.archived_at is null and p.id in (select pv.problem_id from problem_versions pv where pv.quality->'mockExamGeneration'->>'gid' = any (${gidArrL}))
    and not exists (select 1 from mock_exam_set_items i join mock_exam_sets o on o.id = i.exam_set_id and o.archived_at is null and o.status <> 'archived' where i.problem_id = p.id);
  get diagnostics v_n = row_count; raise notice 'lit25 problems archived: %', v_n;
end $rbl$;
`);
  writeFileSync(path.join(OUT, "manifest_lit25.json"), JSON.stringify({ files: filesL, report: repL }, null, 1));
  console.log(JSON.stringify({ files: filesL, report: repL }));
  process.exit(0);
}

